-- Idempotent; vorhandene IDs, Konten, Fortschritte, XP und Freischaltungen bleiben erhalten.
DO $v51_seed$
DECLARE r record; lesson text; category text; level text; min_plan text; plan text; lang text; kapitel text; payload jsonb;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"esx","ordinal":1,"title":"ESX Import","theory":"Aktuelle ESX-Versionen stellen häufig einen Import für das Frameworkobjekt bereit. Die konkrete Einbindung hängt von der installierten Version ab.","example":"shared_script '@es_extended/imports.lua'","example_note":"Die Resource kann danach die bereitgestellten ESX-Funktionen nutzen, wenn das Framework korrekt gestartet ist.","task":"Prüfe die Imports für deine ESX-Version.","q1":{"question":"Welche Aussage erklärt „ESX Import“ richtig?","options":["Der Server kann über die Spieler-ID ein ESX-Spielerobjekt beziehen. Bei Disconnects kann es fehlen.","Aktuelle ESX-Versionen stellen häufig einen Import für das Frameworkobjekt bereit. Die konkrete Einbindung hängt von der installierten Version ab.","Geld kann in ESX als Account abgelegt sein. Eine Kaufentscheidung muss den aktuellen Wert serverseitig lesen."],"correct":1,"explanation":"Aktuelle ESX-Versionen stellen häufig einen Import für das Frameworkobjekt bereit. Die konkrete Einbindung hängt von der installierten Version ab."},"q2":{"question":"Was zeigt das Beispiel zu „ESX Import“?","options":["Das Objekt liefert geprüfte serverseitige Spielerdaten, sofern der Spieler verbunden ist.","Das Kontoobjekt beschreibt den Bankstand; die Integration muss den Rückgabewert validieren.","Die Resource kann danach die bereitgestellten ESX-Funktionen nutzen, wenn das Framework korrekt gestartet ist."],"correct":2,"explanation":"Die Resource kann danach die bereitgestellten ESX-Funktionen nutzen, wenn das Framework korrekt gestartet ist."}},{"course":"esx","ordinal":2,"title":"xPlayer ermitteln","theory":"Der Server kann über die Spieler-ID ein ESX-Spielerobjekt beziehen. Bei Disconnects kann es fehlen.","example":"local xPlayer=ESX.GetPlayerFromId(source)","example_note":"Das Objekt liefert geprüfte serverseitige Spielerdaten, sofern der Spieler verbunden ist.","task":"Beschreibe den Umgang mit nil beim Abruf.","q1":{"question":"Welche Aussage erklärt „xPlayer ermitteln“ richtig?","options":["ESX-Jobs enthalten einen Namen und häufig einen Grade. Der Server muss beides vor geschützten Aktionen prüfen.","ESX.ServerCallback erlaubt eine Anfrage mit späterer Antwort. Der Server entscheidet über die zurückgegebenen Daten.","Der Server kann über die Spieler-ID ein ESX-Spielerobjekt beziehen. Bei Disconnects kann es fehlen."],"correct":2,"explanation":"Der Server kann über die Spieler-ID ein ESX-Spielerobjekt beziehen. Bei Disconnects kann es fehlen."},"q2":{"question":"Was zeigt das Beispiel zu „xPlayer ermitteln“?","options":["Das Objekt liefert geprüfte serverseitige Spielerdaten, sofern der Spieler verbunden ist.","Nicht berechtigte Jobs beenden die Aktion sofort.","Der Callback liefert eine leere Liste an den anfragenden Client."],"correct":0,"explanation":"Das Objekt liefert geprüfte serverseitige Spielerdaten, sofern der Spieler verbunden ist."}},{"course":"esx","ordinal":3,"title":"Job prüfen","theory":"ESX-Jobs enthalten einen Namen und häufig einen Grade. Der Server muss beides vor geschützten Aktionen prüfen.","example":"if xPlayer.job.name ~= \"police\" then return end","example_note":"Nicht berechtigte Jobs beenden die Aktion sofort.","task":"Ergänze eine Grade-Mindestprüfung.","q1":{"question":"Welche Aussage erklärt „Job prüfen“ richtig?","options":["ESX-Jobs enthalten einen Namen und häufig einen Grade. Der Server muss beides vor geschützten Aktionen prüfen.","Geld kann in ESX als Account abgelegt sein. Eine Kaufentscheidung muss den aktuellen Wert serverseitig lesen.","Ein Adapter kapselt Unterschiede zwischen Frameworks, statt überall ESX-spezifische Methoden zu verteilen."],"correct":0,"explanation":"ESX-Jobs enthalten einen Namen und häufig einen Grade. Der Server muss beides vor geschützten Aktionen prüfen."},"q2":{"question":"Was zeigt das Beispiel zu „Job prüfen“?","options":["Das Kontoobjekt beschreibt den Bankstand; die Integration muss den Rückgabewert validieren.","Nicht berechtigte Jobs beenden die Aktion sofort.","Die Fachlogik nutzt getPlayer, nicht direkte ESX-Zugriffe an jeder Stelle."],"correct":1,"explanation":"Nicht berechtigte Jobs beenden die Aktion sofort."}},{"course":"esx","ordinal":4,"title":"Kontostand lesen","theory":"Geld kann in ESX als Account abgelegt sein. Eine Kaufentscheidung muss den aktuellen Wert serverseitig lesen.","example":"local account=xPlayer.getAccount(\"bank\")","example_note":"Das Kontoobjekt beschreibt den Bankstand; die Integration muss den Rückgabewert validieren.","task":"Prüfe einen fehlenden Account.","q1":{"question":"Welche Aussage erklärt „Kontostand lesen“ richtig?","options":["ESX.ServerCallback erlaubt eine Anfrage mit späterer Antwort. Der Server entscheidet über die zurückgegebenen Daten.","Geld kann in ESX als Account abgelegt sein. Eine Kaufentscheidung muss den aktuellen Wert serverseitig lesen.","Aktuelle ESX-Versionen stellen häufig einen Import für das Frameworkobjekt bereit. Die konkrete Einbindung hängt von der installierten Version ab."],"correct":1,"explanation":"Geld kann in ESX als Account abgelegt sein. Eine Kaufentscheidung muss den aktuellen Wert serverseitig lesen."},"q2":{"question":"Was zeigt das Beispiel zu „Kontostand lesen“?","options":["Der Callback liefert eine leere Liste an den anfragenden Client.","Die Resource kann danach die bereitgestellten ESX-Funktionen nutzen, wenn das Framework korrekt gestartet ist.","Das Kontoobjekt beschreibt den Bankstand; die Integration muss den Rückgabewert validieren."],"correct":2,"explanation":"Das Kontoobjekt beschreibt den Bankstand; die Integration muss den Rückgabewert validieren."}},{"course":"esx","ordinal":5,"title":"Server-Callbacks","theory":"ESX.ServerCallback erlaubt eine Anfrage mit späterer Antwort. Der Server entscheidet über die zurückgegebenen Daten.","example":"ESX.RegisterServerCallback(\"garage:list\",function(source,cb) cb({}) end)","example_note":"Der Callback liefert eine leere Liste an den anfragenden Client.","task":"Baue einen Callback mit einer serverseitigen Datenprüfung.","q1":{"question":"Welche Aussage erklärt „Server-Callbacks“ richtig?","options":["Ein Adapter kapselt Unterschiede zwischen Frameworks, statt überall ESX-spezifische Methoden zu verteilen.","Der Server kann über die Spieler-ID ein ESX-Spielerobjekt beziehen. Bei Disconnects kann es fehlen.","ESX.ServerCallback erlaubt eine Anfrage mit späterer Antwort. Der Server entscheidet über die zurückgegebenen Daten."],"correct":2,"explanation":"ESX.ServerCallback erlaubt eine Anfrage mit späterer Antwort. Der Server entscheidet über die zurückgegebenen Daten."},"q2":{"question":"Was zeigt das Beispiel zu „Server-Callbacks“?","options":["Der Callback liefert eine leere Liste an den anfragenden Client.","Die Fachlogik nutzt getPlayer, nicht direkte ESX-Zugriffe an jeder Stelle.","Das Objekt liefert geprüfte serverseitige Spielerdaten, sofern der Spieler verbunden ist."],"correct":0,"explanation":"Der Callback liefert eine leere Liste an den anfragenden Client."}},{"course":"esx","ordinal":6,"title":"Frameworkadapter","theory":"Ein Adapter kapselt Unterschiede zwischen Frameworks, statt überall ESX-spezifische Methoden zu verteilen.","example":"Framework.getPlayer=function(src) return ESX.GetPlayerFromId(src) end","example_note":"Die Fachlogik nutzt getPlayer, nicht direkte ESX-Zugriffe an jeder Stelle.","task":"Entwerfe einen Adapter für Spielerabfragen.","q1":{"question":"Welche Aussage erklärt „Frameworkadapter“ richtig?","options":["Ein Adapter kapselt Unterschiede zwischen Frameworks, statt überall ESX-spezifische Methoden zu verteilen.","Aktuelle ESX-Versionen stellen häufig einen Import für das Frameworkobjekt bereit. Die konkrete Einbindung hängt von der installierten Version ab.","ESX-Jobs enthalten einen Namen und häufig einen Grade. Der Server muss beides vor geschützten Aktionen prüfen."],"correct":0,"explanation":"Ein Adapter kapselt Unterschiede zwischen Frameworks, statt überall ESX-spezifische Methoden zu verteilen."},"q2":{"question":"Was zeigt das Beispiel zu „Frameworkadapter“?","options":["Die Resource kann danach die bereitgestellten ESX-Funktionen nutzen, wenn das Framework korrekt gestartet ist.","Die Fachlogik nutzt getPlayer, nicht direkte ESX-Zugriffe an jeder Stelle.","Nicht berechtigte Jobs beenden die Aktion sofort."],"correct":1,"explanation":"Die Fachlogik nutzt getPlayer, nicht direkte ESX-Zugriffe an jeder Stelle."}},{"course":"fivem","ordinal":1,"title":"Resource-Dependencies","theory":"Das fxmanifest kann Abhängigkeiten deklarieren. Dadurch wird sichtbar, welche anderen Resources vor dem Einsatz benötigt werden.","example":"dependency 'ox_lib'","example_note":"Die Resource deklariert, dass ox_lib vorhanden sein muss.","task":"Definiere eine Abhängigkeit zu einer Bibliothek.","q1":{"question":"Welche Aussage erklärt „Resource-Dependencies“ richtig?","options":["Ein Clienthandler verarbeitet lokale Events. Nicht jede lokale Aktion erfordert einen Netzwerkrundweg.","Das fxmanifest kann Abhängigkeiten deklarieren. Dadurch wird sichtbar, welche anderen Resources vor dem Einsatz benötigt werden.","Ein Export bietet anderen Resources eine klar benannte Funktion. Er eignet sich für stabile APIs zwischen unabhängigen Skripten."],"correct":1,"explanation":"Das fxmanifest kann Abhängigkeiten deklarieren. Dadurch wird sichtbar, welche anderen Resources vor dem Einsatz benötigt werden."},"q2":{"question":"Was zeigt das Beispiel zu „Resource-Dependencies“?","options":["Beim Auslösen des lokalen Events läuft der registrierte Handler.","Andere Resources können die veröffentlichte Funktion aufrufen.","Die Resource deklariert, dass ox_lib vorhanden sein muss."],"correct":2,"explanation":"Die Resource deklariert, dass ox_lib vorhanden sein muss."}},{"course":"fivem","ordinal":2,"title":"Client Event","theory":"Ein Clienthandler verarbeitet lokale Events. Nicht jede lokale Aktion erfordert einen Netzwerkrundweg.","example":"AddEventHandler(\"garage:open\",function() print(\"Garage\") end)","example_note":"Beim Auslösen des lokalen Events läuft der registrierte Handler.","task":"Erstelle einen lokalen Öffnen-Event.","q1":{"question":"Welche Aussage erklärt „Client Event“ richtig?","options":["Ein Server-Netzwerkevent kann vom Client ausgelöst werden. Quellspieler und übergebene Werte müssen auf dem Server validiert werden.","Beim Stop einer Resource sollten temporäre Objekte, Zustände und Fokusfreigaben aufgeräumt werden.","Ein Clienthandler verarbeitet lokale Events. Nicht jede lokale Aktion erfordert einen Netzwerkrundweg."],"correct":2,"explanation":"Ein Clienthandler verarbeitet lokale Events. Nicht jede lokale Aktion erfordert einen Netzwerkrundweg."},"q2":{"question":"Was zeigt das Beispiel zu „Client Event“?","options":["Beim Auslösen des lokalen Events läuft der registrierte Handler.","source bezeichnet den Auslöser; id ist nicht automatisch vertrauenswürdig.","Der Handler erkennt nur den Stop der eigenen Resource."],"correct":0,"explanation":"Beim Auslösen des lokalen Events läuft der registrierte Handler."}},{"course":"fivem","ordinal":3,"title":"Server Event","theory":"Ein Server-Netzwerkevent kann vom Client ausgelöst werden. Quellspieler und übergebene Werte müssen auf dem Server validiert werden.","example":"RegisterNetEvent(\"garage:request\",function(id) local src=source end)","example_note":"source bezeichnet den Auslöser; id ist nicht automatisch vertrauenswürdig.","task":"Prüfe ID und Berechtigung vor einer Aktion.","q1":{"question":"Welche Aussage erklärt „Server Event“ richtig?","options":["Ein Server-Netzwerkevent kann vom Client ausgelöst werden. Quellspieler und übergebene Werte müssen auf dem Server validiert werden.","Ein Export bietet anderen Resources eine klar benannte Funktion. Er eignet sich für stabile APIs zwischen unabhängigen Skripten.","Resmon zeigt den Ressourcenverbrauch einzelner FiveM-Resources. Wiederholte Wait(0)-Schleifen sollten auf ihren echten Bedarf geprüft werden."],"correct":0,"explanation":"Ein Server-Netzwerkevent kann vom Client ausgelöst werden. Quellspieler und übergebene Werte müssen auf dem Server validiert werden."},"q2":{"question":"Was zeigt das Beispiel zu „Server Event“?","options":["Andere Resources können die veröffentlichte Funktion aufrufen.","source bezeichnet den Auslöser; id ist nicht automatisch vertrauenswürdig.","In unterstützten Clientumgebungen zeigt der Befehl laufende Resource-Metriken."],"correct":1,"explanation":"source bezeichnet den Auslöser; id ist nicht automatisch vertrauenswürdig."}},{"course":"fivem","ordinal":4,"title":"exports verwenden","theory":"Ein Export bietet anderen Resources eine klar benannte Funktion. Er eignet sich für stabile APIs zwischen unabhängigen Skripten.","example":"exports(\"getStatus\",function() return \"ok\" end)","example_note":"Andere Resources können die veröffentlichte Funktion aufrufen.","task":"Veröffentliche einen lesenden Status-Export.","q1":{"question":"Welche Aussage erklärt „exports verwenden“ richtig?","options":["Beim Stop einer Resource sollten temporäre Objekte, Zustände und Fokusfreigaben aufgeräumt werden.","Ein Export bietet anderen Resources eine klar benannte Funktion. Er eignet sich für stabile APIs zwischen unabhängigen Skripten.","Das fxmanifest kann Abhängigkeiten deklarieren. Dadurch wird sichtbar, welche anderen Resources vor dem Einsatz benötigt werden."],"correct":1,"explanation":"Ein Export bietet anderen Resources eine klar benannte Funktion. Er eignet sich für stabile APIs zwischen unabhängigen Skripten."},"q2":{"question":"Was zeigt das Beispiel zu „exports verwenden“?","options":["Der Handler erkennt nur den Stop der eigenen Resource.","Die Resource deklariert, dass ox_lib vorhanden sein muss.","Andere Resources können die veröffentlichte Funktion aufrufen."],"correct":2,"explanation":"Andere Resources können die veröffentlichte Funktion aufrufen."}},{"course":"fivem","ordinal":5,"title":"Resource Stop Event","theory":"Beim Stop einer Resource sollten temporäre Objekte, Zustände und Fokusfreigaben aufgeräumt werden.","example":"AddEventHandler(\"onResourceStop\",function(name) if name~=GetCurrentResourceName() then return end end)","example_note":"Der Handler erkennt nur den Stop der eigenen Resource.","task":"Plane Cleanup für ein offenes NUI-Fenster.","q1":{"question":"Welche Aussage erklärt „Resource Stop Event“ richtig?","options":["Resmon zeigt den Ressourcenverbrauch einzelner FiveM-Resources. Wiederholte Wait(0)-Schleifen sollten auf ihren echten Bedarf geprüft werden.","Ein Clienthandler verarbeitet lokale Events. Nicht jede lokale Aktion erfordert einen Netzwerkrundweg.","Beim Stop einer Resource sollten temporäre Objekte, Zustände und Fokusfreigaben aufgeräumt werden."],"correct":2,"explanation":"Beim Stop einer Resource sollten temporäre Objekte, Zustände und Fokusfreigaben aufgeräumt werden."},"q2":{"question":"Was zeigt das Beispiel zu „Resource Stop Event“?","options":["Der Handler erkennt nur den Stop der eigenen Resource.","In unterstützten Clientumgebungen zeigt der Befehl laufende Resource-Metriken.","Beim Auslösen des lokalen Events läuft der registrierte Handler."],"correct":0,"explanation":"Der Handler erkennt nur den Stop der eigenen Resource."}},{"course":"fivem","ordinal":6,"title":"Profiler und Resmon","theory":"Resmon zeigt den Ressourcenverbrauch einzelner FiveM-Resources. Wiederholte Wait(0)-Schleifen sollten auf ihren echten Bedarf geprüft werden.","example":"resmon 1","example_note":"In unterstützten Clientumgebungen zeigt der Befehl laufende Resource-Metriken.","task":"Finde eine unnötig häufige Positionsprüfung.","q1":{"question":"Welche Aussage erklärt „Profiler und Resmon“ richtig?","options":["Resmon zeigt den Ressourcenverbrauch einzelner FiveM-Resources. Wiederholte Wait(0)-Schleifen sollten auf ihren echten Bedarf geprüft werden.","Das fxmanifest kann Abhängigkeiten deklarieren. Dadurch wird sichtbar, welche anderen Resources vor dem Einsatz benötigt werden.","Ein Server-Netzwerkevent kann vom Client ausgelöst werden. Quellspieler und übergebene Werte müssen auf dem Server validiert werden."],"correct":0,"explanation":"Resmon zeigt den Ressourcenverbrauch einzelner FiveM-Resources. Wiederholte Wait(0)-Schleifen sollten auf ihren echten Bedarf geprüft werden."},"q2":{"question":"Was zeigt das Beispiel zu „Profiler und Resmon“?","options":["Die Resource deklariert, dass ox_lib vorhanden sein muss.","In unterstützten Clientumgebungen zeigt der Befehl laufende Resource-Metriken.","source bezeichnet den Auslöser; id ist nicht automatisch vertrauenswürdig."],"correct":1,"explanation":"In unterstützten Clientumgebungen zeigt der Befehl laufende Resource-Metriken."}},{"course":"fivemadmin","ordinal":1,"title":"ACE-Prüfung","theory":"ACE-Berechtigungen werden serverseitig geprüft. Der Client darf Rechte nur anzeigen, nicht selbst vergeben.","example":"IsPlayerAceAllowed(source,\"admin.kick\")","example_note":"Die Funktion prüft ein konkretes Recht für den auslösenden Spieler.","task":"Sichere eine Kick-Aktion ab.","q1":{"question":"Welche Aussage erklärt „ACE-Prüfung“ richtig?","options":["Eine Adminaktion braucht eine gültige Ziel-ID. Spieler können zwischen Anzeigen und Ausführen den Server verlassen.","ACE-Berechtigungen werden serverseitig geprüft. Der Client darf Rechte nur anzeigen, nicht selbst vergeben.","SetNuiFocus steuert, ob Tastatur- und Mausinteraktionen an die NUI gehen. Beim Schließen muss der Fokus freigegeben werden."],"correct":1,"explanation":"ACE-Berechtigungen werden serverseitig geprüft. Der Client darf Rechte nur anzeigen, nicht selbst vergeben."},"q2":{"question":"Was zeigt das Beispiel zu „ACE-Prüfung“?","options":["Ungültige oder nicht verbundene Spieler werden nicht bearbeitet.","Die UI erhält Fokus, bis sie mit false,false wieder freigegeben wird.","Die Funktion prüft ein konkretes Recht für den auslösenden Spieler."],"correct":2,"explanation":"Die Funktion prüft ein konkretes Recht für den auslösenden Spieler."}},{"course":"fivemadmin","ordinal":2,"title":"Ziel-ID validieren","theory":"Eine Adminaktion braucht eine gültige Ziel-ID. Spieler können zwischen Anzeigen und Ausführen den Server verlassen.","example":"local target=tonumber(targetId)\nif not target or not GetPlayerName(target) then return end","example_note":"Ungültige oder nicht verbundene Spieler werden nicht bearbeitet.","task":"Prüfe String, negative ID und getrennten Spieler.","q1":{"question":"Welche Aussage erklärt „Ziel-ID validieren“ richtig?","options":["Die Spielerliste wird serverseitig erzeugt. Browserdaten werden nicht als Quelle für Rollen und IDs vertraut.","Ein Audit-Log hält nachvollziehbar fest, wer wann welche geschützte Aktion auf welchem Ziel ausgeführt hat.","Eine Adminaktion braucht eine gültige Ziel-ID. Spieler können zwischen Anzeigen und Ausführen den Server verlassen."],"correct":2,"explanation":"Eine Adminaktion braucht eine gültige Ziel-ID. Spieler können zwischen Anzeigen und Ausführen den Server verlassen."},"q2":{"question":"Was zeigt das Beispiel zu „Ziel-ID validieren“?","options":["Ungültige oder nicht verbundene Spieler werden nicht bearbeitet.","Der Server durchläuft die tatsächlich verbundenen Spieler.","Der Datensatz enthält die minimalen Informationen zur Nachvollziehbarkeit."],"correct":0,"explanation":"Ungültige oder nicht verbundene Spieler werden nicht bearbeitet."}},{"course":"fivemadmin","ordinal":3,"title":"Server-Snapshot","theory":"Die Spielerliste wird serverseitig erzeugt. Browserdaten werden nicht als Quelle für Rollen und IDs vertraut.","example":"for _,id in ipairs(GetPlayers()) do print(id) end","example_note":"Der Server durchläuft die tatsächlich verbundenen Spieler.","task":"Baue eine Liste mit ID und Namen.","q1":{"question":"Welche Aussage erklärt „Server-Snapshot“ richtig?","options":["Die Spielerliste wird serverseitig erzeugt. Browserdaten werden nicht als Quelle für Rollen und IDs vertraut.","SetNuiFocus steuert, ob Tastatur- und Mausinteraktionen an die NUI gehen. Beim Schließen muss der Fokus freigegeben werden.","Bei vielen Spielern oder Logzeilen sollten Daten in begrenzten Seiten geladen werden. Serverfilter verhindern unnötig große Antworten."],"correct":0,"explanation":"Die Spielerliste wird serverseitig erzeugt. Browserdaten werden nicht als Quelle für Rollen und IDs vertraut."},"q2":{"question":"Was zeigt das Beispiel zu „Server-Snapshot“?","options":["Die UI erhält Fokus, bis sie mit false,false wieder freigegeben wird.","Der Server durchläuft die tatsächlich verbundenen Spieler.","Der Client lädt maximal 20 Ergebnisse pro Anfrage."],"correct":1,"explanation":"Der Server durchläuft die tatsächlich verbundenen Spieler."}},{"course":"fivemadmin","ordinal":4,"title":"NUI-Fokus","theory":"SetNuiFocus steuert, ob Tastatur- und Mausinteraktionen an die NUI gehen. Beim Schließen muss der Fokus freigegeben werden.","example":"SetNuiFocus(true,true)","example_note":"Die UI erhält Fokus, bis sie mit false,false wieder freigegeben wird.","task":"Schreibe den Schließen-Ablauf.","q1":{"question":"Welche Aussage erklärt „NUI-Fokus“ richtig?","options":["Ein Audit-Log hält nachvollziehbar fest, wer wann welche geschützte Aktion auf welchem Ziel ausgeführt hat.","SetNuiFocus steuert, ob Tastatur- und Mausinteraktionen an die NUI gehen. Beim Schließen muss der Fokus freigegeben werden.","ACE-Berechtigungen werden serverseitig geprüft. Der Client darf Rechte nur anzeigen, nicht selbst vergeben."],"correct":1,"explanation":"SetNuiFocus steuert, ob Tastatur- und Mausinteraktionen an die NUI gehen. Beim Schließen muss der Fokus freigegeben werden."},"q2":{"question":"Was zeigt das Beispiel zu „NUI-Fokus“?","options":["Der Datensatz enthält die minimalen Informationen zur Nachvollziehbarkeit.","Die Funktion prüft ein konkretes Recht für den auslösenden Spieler.","Die UI erhält Fokus, bis sie mit false,false wieder freigegeben wird."],"correct":2,"explanation":"Die UI erhält Fokus, bis sie mit false,false wieder freigegeben wird."}},{"course":"fivemadmin","ordinal":5,"title":"Audit-Logs","theory":"Ein Audit-Log hält nachvollziehbar fest, wer wann welche geschützte Aktion auf welchem Ziel ausgeführt hat.","example":"{actor=source,action=\"kick\",target=target,at=os.time()}","example_note":"Der Datensatz enthält die minimalen Informationen zur Nachvollziehbarkeit.","task":"Entwerfe ein Logformat ohne unnötige private Daten.","q1":{"question":"Welche Aussage erklärt „Audit-Logs“ richtig?","options":["Bei vielen Spielern oder Logzeilen sollten Daten in begrenzten Seiten geladen werden. Serverfilter verhindern unnötig große Antworten.","Eine Adminaktion braucht eine gültige Ziel-ID. Spieler können zwischen Anzeigen und Ausführen den Server verlassen.","Ein Audit-Log hält nachvollziehbar fest, wer wann welche geschützte Aktion auf welchem Ziel ausgeführt hat."],"correct":2,"explanation":"Ein Audit-Log hält nachvollziehbar fest, wer wann welche geschützte Aktion auf welchem Ziel ausgeführt hat."},"q2":{"question":"Was zeigt das Beispiel zu „Audit-Logs“?","options":["Der Datensatz enthält die minimalen Informationen zur Nachvollziehbarkeit.","Der Client lädt maximal 20 Ergebnisse pro Anfrage.","Ungültige oder nicht verbundene Spieler werden nicht bearbeitet."],"correct":0,"explanation":"Der Datensatz enthält die minimalen Informationen zur Nachvollziehbarkeit."}},{"course":"fivemadmin","ordinal":6,"title":"Pagination in Adminlisten","theory":"Bei vielen Spielern oder Logzeilen sollten Daten in begrenzten Seiten geladen werden. Serverfilter verhindern unnötig große Antworten.","example":"GET /admin/logs?limit=20&cursor=...","example_note":"Der Client lädt maximal 20 Ergebnisse pro Anfrage.","task":"Füge eine Nächste-Seite-Interaktion hinzu.","q1":{"question":"Welche Aussage erklärt „Pagination in Adminlisten“ richtig?","options":["Bei vielen Spielern oder Logzeilen sollten Daten in begrenzten Seiten geladen werden. Serverfilter verhindern unnötig große Antwor